import { AESModeOfOperationECB } from './lib/aes/index.mjs';
const hex = (b) => Buffer.from(b).toString('hex');
const key = (n) => Uint8Array.from({length:n}, (_,i)=>i);
const pt = Uint8Array.from([0x00,0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,0x99,0xaa,0xbb,0xcc,0xdd,0xee,0xff]);
const want = {16:'69c4e0d86a7b0430d8cdb78070b4c55a',24:'dda97ca4864cdfe06eaf70a0ec0d7191',32:'8ea2b7ca516745bfeafc49904b496089'};
for (const n of [16,24,32]) {
  const c = new AESModeOfOperationECB(key(n));
  const ct = c.encrypt(pt);
  const back = c.decrypt(ct);
  console.log('AES-'+n*8, hex(ct), hex(ct)===want[n] ? 'OK' : 'FAIL(expected '+want[n]+')', 'roundtrip', hex(back)===hex(pt)?'OK':'FAIL');
}
