1	/**
2	 * A faithful port of the slice of Python's `argparse` that the original
3	 * script exercises: long options that store a single string value, the
4	 * implicit `-h/--help`, prefix abbreviation, `--opt=value`, and the exact
5	 * usage/error/help text CPython 3.12 emits.
6	 *
7	 * Deliberately out of scope (unused by the script): positionals, subparsers,
8	 * variable `nargs`, choices, and custom prefix characters.
9	 */
10	
11	/** Mirrors Python's `SystemExit`, raised by `parser.exit()` / `parser.error()`. */
12	export class SystemExit extends Error {
13	  /** @param {number} code process exit status */
14	  constructor(code) {
15	    super(`SystemExit: ${code}`);
16	    this.name = 'SystemExit';
17	    this.code = code;
18	  }
19	}
20	
21	/** argparse's `_negative_number_matcher`. */
22	const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
23	
24	const INDENT = 2;
25	const MAX_HELP_POSITION = 24;
26	
27	/** Terminal width argparse would wrap help text at. */
28	function outputWidth() {
29	  const columns = Number.parseInt(process.env.COLUMNS ?? '', 10);
30	  return (Number.isNaN(columns) ? 80 : columns) - 2;
31	}
32	
33	/** Greedy word wrap, as `textwrap.wrap` behaves on single-spaced help text. */
34	function wrap(text, width) {
35	  const words = text.split(/\s+/).filter(Boolean);
36	  if (words.length === 0) return [];
37	  const lines = [];
38	  let line = words[0];
39	  for (const word of words.slice(1)) {
40	    if (line.length + 1 + word.length <= width) line += ` ${word}`;
41	    else {
42	      lines.push(line);
43	      line = word;
44	    }
45	  }
46	  lines.push(line);
47	  return lines;
48	}
49	
50	/**
51	 * One optional argument declaration.
52	 */
53	class Action {
54	  constructor(optionStrings, { dest, nargs, required = false, help = null, metavar = null, kind = 'store', defaultValue = null }) {
55	    this.optionStrings = optionStrings;
56	    this.dest = dest;
57	    this.nargs = nargs;
58	    this.required = required;
59	    this.help = help;
60	    this.metavar = metavar;
61	    this.kind = kind;
62	    this.defaultValue = defaultValue;
63	  }
64	
65	  /** argparse's `_get_action_name`, used in the "required" error message. */
66	  get name() {
67	    return this.optionStrings.join('/');
68	  }
69	
70	  /** argparse's `_format_action_invocation`. */
71	  get invocation() {
72	    if (this.nargs === 0) return this.optionStrings.join(', ');
73	    const args = this.metavar ?? this.dest.toUpperCase();
74	    return this.optionStrings.map((option) => `${option} ${args}`).join(', ');
75	  }
76	}
77	
78	export class ArgumentParser {
79	  /**
80	   * @param {{ prog?: string, addHelp?: boolean }} [options]
81	   */
82	  constructor({ prog, addHelp = true } = {}) {
83	    this.prog = prog ?? 'prog';
84	    /** @type {Action[]} */
85	    this.actions = [];
86	    /** @type {Map<string, Action>} insertion-ordered, like `_option_string_actions` */
87	    this.optionStringActions = new Map();
88	
89	    if (addHelp) {
90	      this.addArgument(['-h', '--help'], {
91	        action: 'help',
92	        help: 'show this help message and exit',
93	      });
94	    }
95	  }
96	
97	  /**
98	   * Declare an optional argument. Accepts one option string or several.
99	   *
100	   * @param {string|string[]} optionStrings e.g. '--key' or ['-h', '--help']
101	   * @param {{ action?: string, required?: boolean, help?: string, metavar?: string,
102	   *           dest?: string, default?: unknown, type?: unknown }} [options]
103	   */
104	  addArgument(optionStrings, options = {}) {
105	    const strings = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
106	    const isHelp = options.action === 'help';
107	    const longest = strings.find((option) => option.startsWith('--')) ?? strings[0];
108	    const dest = options.dest ?? longest.replace(/^-+/, '').replace(/-/g, '_');
109	
110	    const action = new Action(strings, {
111	      dest,
112	      nargs: isHelp ? 0 : null,
113	      required: options.required ?? false,
114	      help: options.help ?? null,
115	      metavar: options.metavar ?? null,
116	      kind: isHelp ? 'help' : 'store',
117	      defaultValue: options.default ?? null,
118	    });
119	
120	    this.actions.push(action);
121	    for (const option of strings) this.optionStringActions.set(option, action);
122	    return action;
123	  }
124	
125	  // ---------------------------------------------------------------- messages
126	
127	  /** argparse's `format_usage`, minus line wrapping (unused here). */
128	  formatUsage() {
129	    const parts = this.actions.map((action) => {
130	      const option = action.optionStrings[0];
131	      const body = action.nargs === 0 ? option : `${option} ${action.metavar ?? action.dest.toUpperCase()}`;
132	      return action.required ? body : `[${body}]`;
133	    });
134	    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
135	  }
136	
137	  /** argparse's `format_help`. */
138	  formatHelp() {
139	    const width = outputWidth();
140	    const actionMaxLength = this.actions.reduce(
141	      (max, action) => Math.max(max, action.invocation.length + INDENT),
142	      0,
143	    );
144	    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
145	    const helpWidth = Math.max(width - helpPosition, 11);
146	    const actionWidth = helpPosition - INDENT - 2;
147	
148	    let out = `${this.formatUsage()}\noptions:\n`;
149	    for (const action of this.actions) {
150	      const invocation = action.invocation;
151	      if (!action.help) {
152	        out += `${' '.repeat(INDENT)}${invocation}\n`;
153	        continue;
154	      }
155	      const helpLines = wrap(action.help, helpWidth);
156	      if (invocation.length <= actionWidth) {
157	        out += `${' '.repeat(INDENT)}${invocation.padEnd(actionWidth)}  ${helpLines[0] ?? ''}\n`;
158	        for (const line of helpLines.slice(1)) out += `${' '.repeat(helpPosition)}${line}\n`;
159	      } else {
160	        out += `${' '.repeat(INDENT)}${invocation}\n`;
161	        for (const line of helpLines) out += `${' '.repeat(helpPosition)}${line}\n`;
162	      }
163	    }
164	    return out;
165	  }
